//! Exact-source standalone Numbers chart-data transactions.
//!
//! A chart grid is editable only when its drawable owns the inline data.  A
//! non-zero native mediator is admitted only when its resolved typed TN object
//! is the bounded empty dependency shell emitted for standalone charts;
//! table/formula graphs whose caches may be regenerated by Numbers after the
//! package is reopened are refused rather than receiving a misleading
//! grid-only mutation.  The selected chart payload is rewritten with the
//! shared lazy chart-data codec and published through the chart-arrangement
//! archive seam.

#![allow(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    clippy::map_err_ignore,
    clippy::needless_pass_by_value,
    reason = "The package boundary converts bounded native arithmetic and redacts graph failures."
)]

