const CHART_MEDIATOR_FIELD: u32 = 8;
const REFERENCE_IDENTIFIER_FIELD: u32 = 1;
const CHART_MEDIATOR_MESSAGE_TYPE: u32 = 12_006;
const MEDIATOR_SUPER_FIELD: u32 = 1;
const MEDIATOR_ENTITY_ID_FIELD: u32 = 2;
const MEDIATOR_FORMULAS_FIELD: u32 = 3;
const MEDIATOR_COLUMNS_ARE_SERIES_FIELD: u32 = 4;
const MEDIATOR_REGISTERED_FIELD: u32 = 5;
